/* SPDX-License-Identifier: GPL-3.0-or-later
 * Explorer's taskbar as the approved prototype draws it (Wine patch 1140): the prototype's own pixels for its fixed
 * chrome (pw_shell_sprites.h, generated by tools/build-shell-sprites.py from themes/windows11/taskbar), placed where
 * the prototype places them (pw_taskbar_layout.h), its five pinned apps, and its clock in the prototype's own glyphs
 * placed as Chromium places them (pw_shell_glyphs.h, generated by tools/build-shell-glyphs.py; src/pw_text_glyphs.h).
 *
 * A sprite is premultiplied BGRA: GdiAlphaBlend puts it over the button's cleared glass buffer, and the compositor
 * puts that over the bar's acrylic, as Chromium put the element over the bar. Only 96 DPI is measured; at another DPI
 * the taskbar keeps its own drawing (pw_taskbar_sprites_apply). Start's Mihawk mark is drawn, not measured, at every DPI
 * (pw_taskbar_logo_draw). */
#ifndef PW_SHELL_TASKBAR_H
#define PW_SHELL_TASKBAR_H
#include <windows.h>
#include <shellapi.h>
#include <shlobj.h>
#include "pw_shell_sprites.h"
#include "pw_shell_glyphs.h"
#include "pw_taskbar_layout.h"
#include "pw_taskbar_logo.h"
#include "pw_accent.h"   /* the applied theme's accent: the active pill */

#define PW_TASKBAR_PINS 5

/* The prototype's pinned apps (Shell.apps with pinned: true, in its order), as the native Start's built-ins name them.
 * A running window counts as the pin when its process image is the pin's or the pin's console host. A pin starts what
 * launch names in its folder (a CSIDL): the program, or for MihawkBrowser, which lives in the runtime's own folder, the
 * Public Desktop shortcut the title keeps pointing at it (native/proton_wine.cpp). */
static const struct pw_taskbar_pin_app
{
    const WCHAR *name, *image, *host, *launch;
    int folder;
    unsigned sprite;
} pw_taskbar_pin_apps[PW_TASKBAR_PINS] = {
    {L"File Explorer", L"explorer.exe", NULL, L"explorer.exe", CSIDL_WINDOWS, PW_SPRITE_EXPLORER},
    {L"Settings", L"mihawk-settings.exe", NULL, L"mihawk-settings.exe", CSIDL_SYSTEM, PW_SPRITE_SETTINGS},
    {L"Notepad", L"notepad.exe", NULL, L"notepad.exe", CSIDL_SYSTEM, PW_SPRITE_NOTEPAD},
    {L"Terminal", L"cmd.exe", L"conhost.exe", L"cmd.exe", CSIDL_SYSTEM, PW_SPRITE_TERMINAL},
    {L"MihawkBrowser", L"MihawkBrowser.exe", NULL, L"MihawkBrowser.lnk", CSIDL_COMMON_DESKTOPDIRECTORY, PW_SPRITE_BROWSER},
};

static inline BOOL pw_taskbar_sprites_apply(UINT dpi) { return dpi == 96; }

static HBITMAP pw_taskbar_sprite_bitmaps[2][PW_SPRITE_COUNT];

static inline void pw_taskbar_sprite(HDC dc, BOOL dark, unsigned sprite, int x, int y)
{
    const struct pw_shell_sprite *s = &pw_shell_sprites[!!dark][sprite];
    HBITMAP *cached = &pw_taskbar_sprite_bitmaps[!!dark][sprite];
    BLENDFUNCTION blend = {AC_SRC_OVER, 0, 255, AC_SRC_ALPHA};
    HDC source; HGDIOBJ prior;
    if (!*cached)
    {
        BITMAPINFO info = {{sizeof(BITMAPINFOHEADER), s->width, -s->height, 1, 32, BI_RGB}};
        void *bits = NULL;
        *cached = CreateDIBSection(NULL, &info, DIB_RGB_COLORS, &bits, NULL, 0);
        if (!*cached || !bits) return;
        memcpy(bits, s->bgra, (size_t)s->width * s->height * 4);
    }
    if (!(source = CreateCompatibleDC(dc))) return;
    prior = SelectObject(source, *cached);
    GdiAlphaBlend(dc, x, y, s->width, s->height, source, 0, 0, s->width, s->height, blend);
    SelectObject(source, prior); DeleteDC(source);
}

/* A clock line's width in 1/65536 px as the prototype lays it out (src/pw_text_glyphs.h), -1 when a character has no
 * measured glyph (another locale's clock): that clock keeps its own drawing. */
static inline int pw_taskbar_text_width(BOOL dark, const WCHAR *text)
{
    return pw_text_width(&pw_shell_clock_glyphs[!!dark], (const unsigned short *)text, lstrlenW(text));
}

/* A clock line in the prototype's own glyphs over the button's cleared glass buffer, as the sprites go: right-aligned
 * at right with its 17 px line box at top, both from the item's top left. FALSE: drawn nothing. */
static inline BOOL pw_taskbar_text(HDC dc, BOOL dark, const WCHAR *text, const RECT *item, int right, int top)
{
    const PwGlyphFont *font = &pw_shell_clock_glyphs[!!dark];
    int length = lstrlenW(text), advance = pw_taskbar_text_width(dark, text);
    int width = item->right - item->left, height = item->bottom - item->top;
    BITMAPINFO info = {{sizeof(BITMAPINFOHEADER), width, -height, 1, 32, BI_RGB}};
    BLENDFUNCTION blend = {AC_SRC_OVER, 0, 255, AC_SRC_ALPHA};
    void *bits = NULL; HBITMAP bitmap; HDC source; HGDIOBJ prior; BOOL drawn;
    if (advance < 0 || !(bitmap = CreateDIBSection(NULL, &info, DIB_RGB_COLORS, &bits, NULL, 0))) return FALSE;
    if (!bits || !(source = CreateCompatibleDC(dc))) { DeleteObject(bitmap); return FALSE; }
    drawn = pw_text_draw(font, (const unsigned short *)text, length, pw_text_right_aligned(advance, right),
                         top + font->baseline, bits, width, height);
    prior = SelectObject(source, bitmap);
    if (drawn) GdiAlphaBlend(dc, item->left, item->top, width, height, source, 0, 0, width, height, blend);
    SelectObject(source, prior); DeleteDC(source); DeleteObject(bitmap);
    return drawn;
}

static HBITMAP pw_taskbar_logo_bitmap;
static int pw_taskbar_logo_extent;

/* The Start button's Mihawk mark (src/pw_taskbar_logo.h), extent px square at x, y, premultiplied over the button's glass
 * buffer as the sprites go; drawn once for each size, then kept, as a sprite is. */
static inline void pw_taskbar_logo_draw(HDC dc, int x, int y, int extent)
{
    BLENDFUNCTION blend = {AC_SRC_OVER, 0, 255, AC_SRC_ALPHA};
    HDC source; HGDIOBJ prior;
    if (extent <= 0) return;
    if (!pw_taskbar_logo_bitmap || pw_taskbar_logo_extent != extent)
    {
        BITMAPINFO info = {{sizeof(BITMAPINFOHEADER), extent, -extent, 1, 32, BI_RGB}};
        void *bits = NULL; HBITMAP bitmap = CreateDIBSection(NULL, &info, DIB_RGB_COLORS, &bits, NULL, 0);
        if (!bitmap || !bits) { if (bitmap) DeleteObject(bitmap); return; }
        pw_taskbar_logo(bits, extent);
        if (pw_taskbar_logo_bitmap) DeleteObject(pw_taskbar_logo_bitmap);
        pw_taskbar_logo_bitmap = bitmap; pw_taskbar_logo_extent = extent;
    }
    if (!(source = CreateCompatibleDC(dc))) return;
    prior = SelectObject(source, pw_taskbar_logo_bitmap);
    GdiAlphaBlend(dc, x, y, extent, extent, source, 0, 0, extent, extent, blend);
    SelectObject(source, prior); DeleteDC(source);
}

/* The running pill centred at the button's foot, as .tb-pill sits (bottom 0 inside the 1 px border). */
/* The running mark under a button: the prototype's pill. The active one is in the applied theme's accent (src/pw_accent.h,
 * as Settings stored it): its pixels' coverage with that colour, where the sprite holds the default accent. */
static inline void pw_taskbar_pill(HDC dc, BOOL dark, BOOL active, int button_width)
{
    unsigned sprite = active ? PW_SPRITE_PILL_ACTIVE : PW_SPRITE_PILL_RUNNING;
    const struct pw_shell_sprite *s = &pw_shell_sprites[!!dark][sprite];
    int x = (button_width - s->width) / 2;
    unsigned accent = pw_accent_fill(pw_accent_current(), dark), *bits = NULL;
    BITMAPINFO info = {{sizeof(BITMAPINFOHEADER), s->width, -s->height, 1, 32, BI_RGB}};
    BLENDFUNCTION blend = {AC_SRC_OVER, 0, 255, AC_SRC_ALPHA};
    HBITMAP bitmap; HDC source; HGDIOBJ prior;
    if (!active || accent == pw_accent_fill(PW_ACCENT_DEFAULT, dark) ||
        !(bitmap = CreateDIBSection(NULL, &info, DIB_RGB_COLORS, (void **)&bits, NULL, 0)) || !bits)
    {
        pw_taskbar_sprite(dc, dark, sprite, x, 36);
        return;
    }
    for (int i = 0; i < s->width * s->height; ++i)
    {
        unsigned a = s->bgra[i] >> 24;   /* premultiplied: the accent scaled by the pixel's coverage */
        bits[i] = a << 24 | (((accent >> 16) & 255) * a / 255) << 16 | (((accent >> 8) & 255) * a / 255) << 8 |
                  (accent & 255) * a / 255;
    }
    if ((source = CreateCompatibleDC(dc)))
    {
        prior = SelectObject(source, bitmap);
        GdiAlphaBlend(dc, x, 36, s->width, s->height, source, 0, 0, s->width, s->height, blend);
        SelectObject(source, prior); DeleteDC(source);
    }
    DeleteObject(bitmap);
}

/* The pin a process image belongs to, or -1. */
static inline int pw_taskbar_pin_of(const WCHAR *image)
{
    const WCHAR *name = image, *p;
    for (p = image; *p; ++p) if (*p == '\\' || *p == '/') name = p + 1;
    for (int i = 0; i < PW_TASKBAR_PINS; ++i)
        if (!lstrcmpiW(name, pw_taskbar_pin_apps[i].image) ||
            (pw_taskbar_pin_apps[i].host && !lstrcmpiW(name, pw_taskbar_pin_apps[i].host))) return i;
    return -1;
}

static inline BOOL pw_taskbar_launch_pin(HWND owner, int pin)
{
    WCHAR path[MAX_PATH];
    SHELLEXECUTEINFOW execute = {sizeof(execute)};
    if (pin < 0 || pin >= PW_TASKBAR_PINS) return FALSE;
    if (FAILED(SHGetFolderPathW(NULL, pw_taskbar_pin_apps[pin].folder, NULL, SHGFP_TYPE_CURRENT, path))) return FALSE;
    if (lstrlenW(path) + 1 + lstrlenW(pw_taskbar_pin_apps[pin].launch) >= MAX_PATH) return FALSE;
    lstrcatW(path, L"\\"); lstrcatW(path, pw_taskbar_pin_apps[pin].launch);
    execute.fMask = SEE_MASK_NOASYNC; execute.hwnd = owner; execute.lpFile = path; execute.nShow = SW_SHOWNORMAL;
    return ShellExecuteExW(&execute);
}
#endif
